const compressPage = async (page) => {
  const compressed = await compress(page.data);
  const success = await cas(
    page.state,
    PageState.ACTIVE,
    PageState.COMPRESSED
  );
  if (success) {
    page.compressedData = compressed;
    updatePageTable(page.virtAddr, page.compressedData);
  }
  return success;
};

// State transition: COMPRESSED -> ACTIVE (on fault)
const decompressPage = async (page) => {
  const decompressed = await decompress(page.compressedData);
  const success = await cas(
    page.state,
    PageState.COMPRESSED,
    PageState.ACTIVE
  );
  if (success) {
    page.data = decompressed;
    mapToLinearAddr(page.virtAddr, page.data);
  }
  return success;
};
```

